package com.bank.jvm.container;

import java.util.logging.Logger;

public class ContainerSizingAdvisor {
    private static final Logger log = Logger.getLogger(ContainerSizingAdvisor.class.getName());

    public static void main(String[] args) {
        long podLimitMb = 2048; // from the cgroup / k8s limit
        FootprintReporter reporter = new FootprintReporter();
        reporter.report();

        SizingPolicy zgc = new SizingPolicy("ZGC", 72.0); // concurrent + colored-pointer overhead
        SizingPolicy g1  = new SizingPolicy("G1", 80.0);  // needs less headroom than ZGC

        long zgcHeap = zgc.recommendedHeapMb(podLimitMb);
        long g1Heap  = g1.recommendedHeapMb(podLimitMb);
        log.info(() -> "Pod limit=" + podLimitMb + "MB");
        log.info(() -> zgc.name() + " recommended -Xmx ~ " + zgcHeap + "MB (" + zgc.percent() + "%)");
        log.info(() -> g1.name()  + " recommended -Xmx ~ " + g1Heap  + "MB (" + g1.percent()  + "%)");

        long dangerousHeap = (long) (podLimitMb * 0.90);
        if (zgc.isTooClose(dangerousHeap, podLimitMb)) {
            log.severe(() -> "DANGER: heap at " + dangerousHeap + "MB (90%) leaves too little "
                    + "for non-heap; cgroup will OOMKill during a GC cycle");
        }
    }
}

// ─── Would be in SizingPolicy.java in a real project ───
class SizingPolicy {
    private final String name;
    private final double percent;

    SizingPolicy(String name, double percent) {
        this.name = name;
        this.percent = percent;
    }
    String name() { return name; }
    double percent() { return percent; }

    long recommendedHeapMb(long podLimitMb) {
        return (long) (podLimitMb * (percent / 100.0));
    }
    // "Too close" if heap leaves less than ~20% for non-heap memory.
    boolean isTooClose(long heapMb, long podLimitMb) {
        return (podLimitMb - heapMb) < (podLimitMb * 0.20);
    }
}
