package com.bank.jvm.container;

import java.lang.management.ManagementFactory;
import java.lang.management.MemoryMXBean;
import java.lang.management.MemoryUsage;
import java.util.logging.Logger;

class FootprintReporter {
    private static final Logger log = Logger.getLogger(FootprintReporter.class.getName());
    private final MemoryMXBean memoryBean = ManagementFactory.getMemoryMXBean();

    void report() {
        MemoryUsage heap = memoryBean.getHeapMemoryUsage();
        MemoryUsage nonHeap = memoryBean.getNonHeapMemoryUsage();
        long heapMaxMb = heap.getMax() / (1024 * 1024);
        long nonHeapUsedMb = nonHeap.getUsed() / (1024 * 1024);
        int threads = ManagementFactory.getThreadMXBean().getThreadCount();
        log.info(() -> "Heap max=" + heapMaxMb + "MB | non-heap used=" + nonHeapUsedMb
                + "MB | threads=" + threads + " (each ~1MB stack)");
        log.info("Remember: Metaspace + code cache + stacks + direct buffers + "
                + "page cache ALL count against the pod limit");
    }
}
